let palette = ['#39c5bb', '#ff69b4', '#3a86ff', '#ffffff'];
let ctx;
let centerX, centerY;
let animations = [];

function setup() {
	createCanvas(900, 900);
	rectMode(CENTER);
	colorMode(HSB, 360, 100, 100, 100);
	textAlign(CENTER, CENTER);
	ctx = drawingContext;
	centerX = width / 2;
	centerY = height / 2;

	let sep = 13;
	animations = tiling(centerX, centerY, width, height, sep, sep);
}

function draw() {
	background('#01040d');

	for (let i of animations) {
		i.run();
	}

	if(frameCount % (60 * 4) == 0){
		reset();
	}
}

function tiling(x, y, w, h, rows, columns) {
	let cellW = w / columns;
	let cellH = h / rows;
	let remainingCells = rows * columns;
	let arr = [];

	let grids = Array.from({ length: columns }, () =>
		Array(rows).fill(false)
	);

	while (remainingCells > 0) {
		let wh = random([[1, 1], [2, 1], [1, 2], [2, 2], [1, 1], [2, 2]]);
		let tileW = wh[0];
		let tileH = wh[1];
		let startCol = int(random(columns - tileW + 1));
		let startRow = int(random(rows - tileH + 1));
		let canPlace = true;
		for (let rowOffset = 0; rowOffset < tileH; rowOffset++) {
			for (let colOffset = 0; colOffset < tileW; colOffset++) {
				if (grids[startCol + colOffset][startRow + rowOffset]) {
					canPlace = false;
					break;
				}
			}
			if (!canPlace) break;
		}
		if (canPlace) {
			for (let j = 0; j < tileH; j++) {
				for (let i = 0; i < tileW; i++) {
					grids[startCol + i][startRow + j] = true;
				}
			}
			let tileWidth = tileW * cellW;
			let tileHeight = tileH * cellH;
			let tileCenterX = (startCol * cellW) + (tileWidth / 2) + (x - (w / 2));
			let tileCenterY = (startRow * cellH) + (tileHeight / 2) + (y - (h / 2));
			let margin = min(tileWidth, tileHeight) * 0;
			arr.push(createAnimations(tileCenterX, tileCenterY, tileWidth - margin, tileHeight - margin));
			remainingCells -= tileW * tileH;
		}
	}

	return arr;
}

function createAnimations(x, y, w, h) {
	let anim;
	let clr = color(random(palette));
	let margin = 0.85;
	if (w == h) {
		let type = int(random(5));
		if (type == 0) anim = new SquareAnimation01(x, y, w * margin, clr);
		if (type == 1) anim = new SquareAnimation02(x, y, w * margin, clr);
		if (type == 2) anim = new SquareAnimation03(x, y, w * margin, clr);
		if (type == 3) anim = new SquareAnimation04(x, y, w * margin, clr);
		if (type == 4) anim = new SquareAnimation05(x, y, w * margin, clr);
		if (type == 4) anim = new SquareAnimation06(x, y, w * margin, clr);
	} else {
		let type = int(random(5));
		if (type == 0) anim = new RectAnimation01(x, y, w * margin, h * margin, clr);
		if (type == 1) anim = new RectAnimation02(x, y, w * margin, h * margin, clr);
		if (type == 2) anim = new RectAnimation03(x, y, w * margin, h * margin, clr);
		if (type == 3) anim = new RectAnimation04(x, y, w * margin, h * margin, clr);
		if (type == 4) anim = new RectAnimation05(x, y, w * margin, h * margin, clr);
	}

	return anim;
}


function drawGrid(x, y, w, cellCount) {
	let cellW = w / cellCount;
	for (let i = 0; i < cellCount; i++) {
		for (let j = 0; j < cellCount; j++) {
			let cellX = j * cellW + cellW / 2 + x - (w / 2);
			let cellY = i * cellW + cellW / 2 + y - (w / 2);
			rect(cellX, cellY, cellW);
		}
	}
}

function reset() {
	animations = [];

	let sep = int(random(10, 18));
	animations = tiling(centerX, centerY, width, height, sep, sep);
}

