class SquareAnimation01 {
	constructor(x, y, w, clr) {
		this.x = x;
		this.y = y;
		this.w = w;
		this.clr = clr;
		this.ang = random([0, PI / 2, -PI / 2]);
		this.timer = 0;
		this.count = int(random(5, 9));
		this.rnds = [];
		for (let i = 0; i < this.count; i++) {
			this.rnds[i] = random();
		}
		this.barLength = [];
		for (let i = 0; i < this.count; i++) {
			this.barLength[i] = 0;
		}
	}

	show() {
		push();
		translate(this.x, this.y);
		rotate(this.ang);
		noStroke();
		let ww = (this.w / this.count);
		this.clr.setAlpha(90);
		fill(this.clr);

		this.clr.setAlpha(100);
		strokeWeight(this.w / 100);
		stroke(this.clr);
		for (let i = 0; i < this.count; i++) {
			let xx = map(i, 0, this.count - 1, -1, 1) * ((this.w - ww) / 2);
			let hh = this.barLength[i];
			let yy = (this.w / 2) - (hh / 2);
			rect(xx, yy, ww * 0.5, hh);
		}

		strokeWeight(this.w / 90);
		stroke(this.clr);
		line(-this.w / 2, this.w / 2, this.w / 2, this.w / 2);
		pop();
	}

	move() {
		for (let i = 0; i < this.count; i++) {
			let noiseVal = noise(this.timer / lerp(50, 300, this.rnds[i]), this.rnds[i] * 10000);
			let rawLength = map(noiseVal, 0, 1, -this.w / 2, this.w * 1.4);
			let barLen = constrain(rawLength, 1, this.w);
			this.barLength[i] = barLen;
		}
		this.timer++;
	}

	run() {
		this.show();
		this.move();
	}
}

class SquareAnimation02 {
	constructor(x, y, w, clr) {
		this.x = x;
		this.y = y;
		this.w = w;
		this.clr = clr;
		this.ang = int(random(4)) * (TAU / 4);
		this.scaleX = random([-1, 1]);
		this.timer = random(194823);
		this.periodA = random(200, 450);
		this.periodB = random(200, 450);
	}

	show() {
		push();
		translate(this.x, this.y);
		noFill();
		stroke(this.clr);
		strokeWeight(this.w * 0.01);
		push();
		for (let i = 0; i < 100; i++) {
			if (i % 5 == 0) {
				line(this.w * 0.5, 0, this.w * 0.35, 0);
			} else {
				line(this.w * 0.45, 0, this.w * 0.4, 0);
			}
			rotate(TAU / 100);
		}
		pop();
		let a = (((cos(this.timer / this.periodA) * sin(this.timer / this.periodB)) + 1) / 2) * TAU * 2;
		rotate(a);
		line(-this.w * 0.1, 0, this.w * 0.4, 0);
		circle(0, 0, this.w * 0.03);

		noStroke();
		fill(this.clr);
		circle(this.w * 0.25, 0, this.w * 0.05);


		pop();
	}

	move() {
		this.timer++;
	}

	run() {
		this.show();
		this.move();
	}
}

class SquareAnimation03 {
	constructor(x, y, w, clr) {
		this.x = x;
		this.y = y;
		this.w = w;
		this.clr = color(clr);
		this.ang = int(random(4)) * (TAU / 4);
		this.scaleX = random([-1, 1]);
		this.timer = 0;
		let posCount = int(random(1, 4));
		this.pos = [];
		for (let i = 0; i < posCount; i++) {
			let r = this.w * 0.5 * random();
			let a = TAU * random();
			let xx = r * cos(a);
			let yy = r * sin(a);
			this.pos.push(createVector(xx, yy));
		}
	}

	show() {
		let gradient = ctx.createConicGradient(0, 0, 0);
		this.clr.setAlpha(80);
		gradient.addColorStop(0, this.clr);
		this.clr.setAlpha(0);
		gradient.addColorStop(0.3, this.clr);

		push();
		translate(this.x, this.y);
		scale(-1, 1);
		noFill();
		this.clr.setAlpha(50);
		stroke(this.clr);
		strokeWeight(this.w * 0.01);
		for (let i = 0; i < 6; i++) {
			let d = map(i, 0, 5, 0, this.w);
			circle(0, 0, d);
		}
		line(-this.w / 2, -this.w / 2, this.w / 2, this.w / 2);
		line(-this.w / 2, this.w / 2, this.w / 2, -this.w / 2);

		this.clr.setAlpha(80);
		fill(this.clr);
		for (let i of this.pos) {
			circle(i.x, i.y, this.w * 0.03);
		}

		push();
		rotate(this.ang);
		fill(0);
		noStroke();
		ctx.fillStyle = gradient;
		circle(0, 0, this.w);

		pop();
		pop();
	}

	move() {
		this.ang -= TAU / 180;
		this.timer++;
	}

	run() {
		this.show();
		this.move();
	}
}


class SquareAnimation04 {
