	}
}

class SquareAnimation05 {
	constructor(x, y, w, clr) {
		this.x = x;
		this.y = y;
		this.w = w;
		this.clr = clr;
		this.ang = int(random(4)) * (TAU / 4);
		this.scaleX = random([-1, 1]);
		this.timer = 0;
		this.arcs = [];
		let count = 3;
		for (let i = 0; i < count; i++) {
			let thickness = (this.w * random(0.1, 0.02));
			let d = map(i, 0, count, this.w, 0) - (thickness / 2);
			let a = random(TAU);
			let av = random(-1, 1) * 0.02;
			let n = int(random(2, 8)) * 2;
			let alp = random(60, 100);
			this.arcs.push({ d: d, tkn: thickness, a: a, av: av, n: n, alp: alp })
		}
	}

	show() {
		push();
		translate(this.x, this.y);
		strokeCap(SQUARE);
		noFill();
		for (let i of this.arcs) {
			this.clr.setAlpha(i.alp);
			strokeWeight(i.tkn);
			stroke(this.clr);
			rotate(i.a);
			for (let j = 0; j < i.n; j++) {
				let a = (TAU / i.n) * j;
				if (j % 2 == 0) {
					arc(0, 0, i.d, i.d, a, a + (TAU / i.n));
				}
			}
		}
		pop();
	}

	move() {
		for (let i of this.arcs) {
			i.a += i.av;
		}
		this.timer++;
	}

	run() {
		this.show();
		this.move();
	}
}

class SquareAnimation06 {
	constructor(x, y, w, clr) {
		this.x = x;
