	}

	show() {
		push();
		translate(this.x, this.y);
		stroke(this.clr);
		fill(this.clr);
		strokeWeight(width / 1000);
		textFont('Geo');
		textSize(this.w * 0.4);
		text(nf(this.amount, 2, 0), 0, -this.w * 0.03);

		noFill();
		circle(0, 0, this.w * 0.95);
		circle(0, 0, this.w * 0.65);

		strokeWeight(this.w * 0.1);
		strokeCap(SQUARE);
		ctx.setLineDash([this.w * PI / 60, this.w * PI / 120]);
		arc(0, 0, this.w * 0.8, this.w * 0.8, -PI / 2, (TAU * (this.amount / 100)) - PI / 2);
		pop();
	}

	move() {
		if (random() < 0.5) {
			this.amount += random(-1, 1);
		}
		this.amount = constrain(this.amount, 0, 100);
	}

	run() {
		this.show();
		this.move();
	}
}

