class RectAnimation01 {
	constructor(x, y, w, h, clr) {
		this.x = x;
		this.y = y;
		this.w = w;
		this.h = h;
		this.clr = clr;
		this.timer = int(random(12938));
		this.ang = 0;
		this.scaleX = random([-1, 1]);
		if (w < h) {
			this.ang = PI / 2;
			let tmp = this.w;
			this.w = this.h
			this.h = tmp;
		}

		this.amp = this.h * 0.5;
		this.freq1 = PI * int(random(1, 5));
		this.freq2 = PI * int(random(1, 5));
		this.period1 = int(random(15, 120));
		this.period2 = int(random(25, 120));
	}

	show() {
		push();
		translate(this.x, this.y);
		rotate(this.ang);
		scale(this.scaleX, 1);
		noFill();
		stroke(this.clr);
		strokeWeight(this.w / 150);
		line(-this.w / 2, 0, this.w / 2, 0);
		line(0, -this.h / 2, 0, this.h / 2);
		strokeWeight(this.w / 70);
		beginShape();
		vertex(-this.w / 2, 0);
		let count = 100;
		for (let i = 0; i < count; i++) {
			let nrm = norm(i, 0, count);
			let xx = lerp(-this.w * 0.5, this.w * 0.5, nrm);
			let r = this.amp * sin(lerp(0, PI, nrm));
			let yy = r * sin((this.freq1 * nrm) + this.timer / this.period1) * cos((this.freq2 * nrm) + this.timer / this.period2);
			vertex(xx, yy);
		}
		endShape();
		pop();
	}

	move() {
		this.timer++;
	}

	run() {
		this.show();
		this.move();
	}
}

class RectAnimation02 {
	constructor(x, y, w, h, clr) {
		this.x = x;
		this.y = y;
		this.w = w;
		this.h = h;
		this.clr = clr;
		this.timer = int(random(12938));
		this.ang = 0;
		if (w < h) {
			this.ang = PI / 2;
			let tmp = this.w;
			this.w = this.h
			this.h = tmp;
		}
		this.count = 25;
		this.phaseOffset = random(100, 200);
		this.scaleY = random([-1, 1]);
	}

	show() {
		push();
		translate(this.x, this.y);
		scale(1, this.scaleY);
		rotate(this.ang);
		translate(0, this.h / 2);
		noStroke();
		rotate(PI);
		for (let i = 0; i < this.count; i++) {
			if (i < this.amount) {
				let alph = map(i, 0, this.count, 20, 100);
				this.clr.setAlpha(alph);
				fill(this.clr);
				beginShape();
				vertex(this.w * 0.25 * cos(0), this.w * 0.25 * sin(0));
				vertex(this.w * 0.5 * cos(0), this.w * 0.5 * sin(0));
				vertex(this.w * 0.5 * cos((PI / 25) * 0.75), this.w * 0.5 * sin((PI / 25) * 0.75));
				vertex(this.w * 0.25 * cos((PI / 25) * 0.75), this.w * 0.25 * sin((PI / 25) * 0.75));
				endShape();
			}
			rotate(PI / this.count);
		}
		noFill();
		this.clr.setAlpha(80);
		stroke(this.clr);
		arc(0, 0, this.w * 0.4, this.w * 0.4, PI, TAU);
		for (let a = PI; a <= TAU; a += PI / 10) {
			line(this.w * 0.175 * cos(a), this.w * 0.175 * sin(a), this.w * 0.225 * cos(a), this.w * 0.225 * sin(a));
		}
		line(this.w * 0.2, 0, this.w / 2, 0);
		line(-this.w * 0.2, 0, -this.w / 2, 0);
		pop();
	}

	move() {
		let ns = constrain((noise(this.timer / this.phaseOffset) * 2) - 0.5, 0, 1);
		this.amount = int(25 * ns);
		this.timer++;
	}

	run() {
		this.show();
		this.move();
	}
}

class RectAnimation03 {
	constructor(x, y, w, h, clr) {
		this.x = x;
		this.y = y;
		this.w = w;
		this.h = h;
		this.ang = 0;
		if (w < h) {
			this.ang = (PI / 2) + PI * random([0, 1]);
			let tmp = this.w;
			this.w = this.h
			this.h = tmp;
		}
		this.clr = clr;
		this.timer = 0;

		let count = int(random(5, 10));
		this.points = [];
		for (let i = 0; i < count; i++) {
			this.points.push(random());
		}
		this.rnds = [];
		for (let i = 0; i < count; i++) {
			this.rnds.push(random());
		}
		this.scl = [];
		for (let i = 0; i < count; i++) {
			this.scl.push(random(10, 200));
		}
	}

	show() {
		push();
		translate(this.x, this.y);
		rotate(this.ang);
		noFill();
		stroke(this.clr);
		strokeWeight(this.w * 0.01);
		let ww = this.w / 6;
		for (let i = 0; i <= 6; i++) {
			for (let j = 0; j <= 3; j++) {
				let xx = i * ww - (this.w / 2);
				let yy = j * ww - (this.h / 2);
				point(xx, yy);
			}
		}
		strokeWeight(this.w * 0.005);
		beginShape();
		for (let i = 0; i < this.points.length; i++) {
			let xx = map(i, 0, this.points.length - 1, -this.w / 2, this.w / 2);
			let yy = (this.points[i] - 0.5) * this.h;
			vertex(xx, yy);
		}

		endShape();

		noStroke();
		fill(this.clr);
		for (let i = 0; i < this.points.length; i++) {
			let xx = map(i, 0, this.points.length - 1, -this.w / 2, this.w / 2);
			let yy = (this.points[i] - 0.5) * this.h;
			circle(xx, yy, this.h * 0.05);
		}
		pop();
	}

	move() {
		this.timer++;
		for (let i = 0; i < this.points.length; i++) {
			this.points[i] = noise(i * 1000, this.timer / this.scl[i], this.rnds[i]);
		}
	}

	run() {
		this.show();
		this.move();
	}
}

class RectAnimation04 {
	constructor(x, y, w, h, clr) {
		this.x = x;
		this.y = y;
		this.w = w;
		this.h = h;
		this.ang = 0;
		if (w < h) {
			this.ang = (PI / 2) + PI * random([0, 1]);
			let tmp = this.w;
			this.w = this.h
			this.h = tmp;
		}
		this.clr = clr;
		this.timer = 0;
		this.columns = 5;
		this.coin = [];
		for (let i = 0; i < (this.columns * (this.columns * 2)); i++) {
			this.coin.push(random([false, true]));
		}
	}

	show() {
		push();
		translate(this.x, this.y);
		rotate(this.ang);
		noStroke();
		let ww = this.w / (this.columns * 2);
		let cnt = 0;
		for (let i = 0; i < (this.columns * 2); i++) {
			for (let j = 0; j < this.columns; j++) {
				let xx = i * ww + (ww / 2) - this.w / 2;
				let yy = j * ww + (ww / 2) - this.h / 2;
				if (this.coin[cnt]) {
					this.clr.setAlpha(90);
				} else {
					this.clr.setAlpha(50);
				}
				fill(this.clr);

				square(xx, yy, ww * 0.75, ww * 0.1);
				cnt++;
			}
		}
		pop();
	}

	move() {
		this.timer++;
		if (this.timer % int(random(10, 100)) == 0) {
			this.coin = [];
			for (let i = 0; i < (this.columns * (this.columns * 2)); i++) {
				this.coin.push(random([false, true]));
			}
		}
	}

	run() {
		this.show();
		this.move();
	}
}

